// Edit a runtime v2 diagram through its source: the <script type="text/nm-diagram"> DSL block. The drawing itself is
// generated by the runtime and never written back (runtime contract, "Generated markup"). Saving sends one setText
// on the script (a minimal splice of the changed lines), then reloads the preview so the runtime draws it again.
import { useEffect, useRef, useState } from 'preact/hooks';
import { postOps } from './actions.ts';
import { reloadPreview } from './events.ts';
import { elementByKey } from './frame.ts';
import { Icon } from './icons.tsx';
import { banner, diagramSource, t } from './state.ts';

export function DiagramDialog() {
  const s = t.value;
  const ref = useRef<HTMLDialogElement>(null);
  const [text, setText] = useState('');
  const [original, setOriginal] = useState('');
  const open = diagramSource.value;

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      const current = elementByKey(open.sourceKey)?.textContent ?? '';
      setText(current);
      setOriginal(current);
      dialog.showModal();
    }
    if (!open && dialog.open) dialog.close();
  }, [open?.sourceKey]);

  const save = async () => {
    if (!open) return;
    try {
      if (text !== original) {
        await postOps([{ kind: 'setText', id: open.sourceKey, text }], { label: 'Edit diagram source' });
        await reloadPreview();
      }
      diagramSource.value = null;
    } catch (error) {
      banner.value = { kind: 'error', message: error instanceof Error ? error.message : String(error) };
    }
  };

  return (
    <dialog ref={ref} class="export-dialog raised diagram-dialog" aria-labelledby="diagram-title" data-testid="diagram-dialog"
      onClose={() => { diagramSource.value = null; }}>
      <div class="export-head">
        <h2 id="diagram-title">{s.diagramTitle}</h2>
        <button type="button" class="round raised-s" aria-label={s.diagramCancel} title={s.diagramCancel} onClick={() => { diagramSource.value = null; }}>
          <Icon name="close" />
        </button>
      </div>
      <p class="export-intro">{s.diagramHint}</p>
      {/* The DSL reads left to right (ids and arrows); Arabic labels inside it still shape and order correctly. */}
      <textarea dir="ltr" spellcheck={false} rows={10} value={text} aria-label={s.diagramTitle}
        onInput={(e) => setText(e.currentTarget.value)} data-testid="diagram-source" />
      <div class="dialog-actions">
        <button type="button" class="raised-s" onClick={() => { diagramSource.value = null; }}>{s.diagramCancel}</button>
        <button type="button" class="raised-s" disabled={text === original} onClick={() => void save()} data-testid="diagram-save">{s.diagramSave}</button>
      </div>
    </dialog>
  );
}
